from pathlib import Path
p=Path('app/restaurant.tsx')
s=p.read_text(encoding='utf-8-sig')
s=s.replace("[galleryFilter,setGalleryFilter]=useState('all');", "[bookOpen,setBookOpen]=useState(false);")
s=s.replace(".then(d=>setCatalog(Array.isArray(d)?d:(d.images||d.assets||[])))", ".then((d:unknown)=>{if(Array.isArray(d))setCatalog(d as Asset[])})")
s=s.replace("useEffect(()=>{if(lightbox)galleryDialog.current?.showModal()},[lightbox]);", "useEffect(()=>{if(lightbox)galleryDialog.current?.showModal()},[lightbox]);\n useEffect(()=>{const previous=document.body.style.overflow;if(nav||lightbox||bookOpen)document.body.style.overflow='hidden';return()=>{document.body.style.overflow=previous}},[nav,lightbox,bookOpen]);")
s=s.replace("booking.current?.showModal();setNav(false)","booking.current?.showModal();setBookOpen(true);setNav(false)")
s=s.replace('src={img(id)} alt={alt} loading=', 'src={img(id)} srcSet={`${img(id).replace(".webp","-small.webp")} 640w, ${img(id)} 1600w`} sizes={priority?"100vw":"(max-width: 767px) 92vw, (max-width: 1200px) 50vw, 45vw"} alt={alt} loading=')
s=s.replace("Pan y A.O.V.E.: 1,80 € por persona, según carta.","Pan y A.O.V.E.: 2,30 €. Mantequilla: 1,20 €, según carta.")
s=s.replace("Bread and olive oil: see the extras section for the official price.","Bread and olive oil: €2.30. Butter: €1.20, as listed on the menu.")
s=s.replace('<dialog className="booking-dialog" ref={booking}', '<dialog className="booking-dialog" aria-labelledby="booking-title" ref={booking} onClose={()=>setBookOpen(false)}')
s=s.replace("<h2>{t('Un sitio','A place')}","<h2 id=\"booking-title\">{t('Un sitio','A place')}")
s=s.replace("<h2>{t('Así sería','Your next')}","<h2 id=\"booking-title\">{t('Así sería','Your next')}")
s=s.replace('<dialog className="lightbox" ref={galleryDialog}', '<dialog className="lightbox" aria-labelledby="photo-title" ref={galleryDialog}')
s=s.replace('<span>{lightbox.name}</span><span>', '<span id="photo-title">{lightbox.name}</span><span>')
s=s.replace('<span>{lightbox.id} / {catalog.length}</span>', '<span>{lightbox.id} / {catalog.length}</span><a className="download-photo" href={`/4k/${String(lightbox.id).padStart(2,\'0\')}.jpg`} download>{t(\'Descargar 4K\',\'Download 4K\')}<ArrowDown size={13}/></a>')
p.write_text(s,encoding='utf-8')
